+    OpParams::Slot {
+        links: camcraft_app::links::Links::PLANAR,
+        a: camcraft_app::geo2d::Point2::new(15.0, 30.0),
+        b: camcraft_app::geo2d::Point2::new(45.0, 30.0),
+        width: 12.0,
