+fn fp(stepover: f64, blend: bool, radius: Option<f64>) -> FaceParams {
+    FaceParams {
+        holes: Default::default(),
+        tool_diameter: 2.0 * FACE_R,
+        stepover,
+        clearance_z: 5.0,
+        cut_z: -2.0,
+        top_z: None,
+        stepdown: None,
+        feed: 500.0,
+        plunge_feed: 100.0,
+        climb: true,
+        blend_turns: blend,
